// db.js - an in-memory Postgres, ready to use. You do NOT edit this file.
//
// It behaves like real PostgreSQL (same SQL, same pool.query, same $1
// parameters) but lives in memory, so there is nothing to install. It is seeded
// with 8 books and 200 loans, generated the SAME way every run, so the numbers
// on your dashboard never change between runs. This is the REVIEWER, so the data
// is different from the exam - practise the moves, not the answers.
import { newDb } from 'pg-mem'

const SCHEMA = `
  CREATE TABLE books (
    id     SERIAL PRIMARY KEY,
    title  TEXT NOT NULL,
    author TEXT NOT NULL,
    genre  TEXT NOT NULL
  );
  CREATE TABLE loans (
    id          SERIAL PRIMARY KEY,
    book_id     INTEGER NOT NULL REFERENCES books(id),
    member      TEXT NOT NULL,
    days_out    INTEGER NOT NULL,
    borrowed_at DATE NOT NULL
  );
`

// Two authors (Rizal, Herbert) own two titles each, so "busiest author" only
// comes out right if you GROUP BY author, not by title.
const BOOKS = [
  ['The Silent Patient', 'Alex Michaelides', 'mystery'],
  ['Noli Me Tangere', 'Jose Rizal', 'history'],
  ['El Filibusterismo', 'Jose Rizal', 'history'],
  ['Dune', 'Frank Herbert', 'sci-fi'],
  ['Dune Messiah', 'Frank Herbert', 'sci-fi'],
  ['Pride and Prejudice', 'Jane Austen', 'romance'],
  ['Gone Girl', 'Gillian Flynn', 'mystery'],
  ['Leaves of Grass', 'Walt Whitman', 'poetry'],
]
const MEMBERS = ['Reyes', 'Santos', 'Cruz', 'Bautista', 'Garcia', 'Torres']

// A tiny deterministic generator (a linear congruential generator). No
// randomness, so everyone's database is identical. NEW seed for the reviewer.
function makeRows(n) {
  let x = 20260910
  const next = () => (x = (x * 1103515245 + 12345) & 0x7fffffff)
  const rows = []
  for (let i = 0; i < n; i++) {
    const bits = () => (next() >>> 8) & 0xffff   // high bits: the low bits of an LCG barely change
    const book_id = 1 + (bits() % BOOKS.length)
    const member = MEMBERS[bits() % MEMBERS.length]
    const days_out = bits() % 30                 // 0-29 days
    const month = 1 + (bits() % 6)               // Jan-Jun 2026
    const day = 1 + (bits() % 28)
    const borrowed_at = `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    rows.push({ book_id, member, days_out, borrowed_at })
  }
  return rows
}

const db = newDb()
db.public.none(SCHEMA)
for (const [title, author, genre] of BOOKS) {
  db.public.none(`INSERT INTO books (title, author, genre) VALUES ('${title.replace(/'/g, "''")}', '${author.replace(/'/g, "''")}', '${genre}')`)
}
for (const r of makeRows(200)) {
  db.public.none(
    `INSERT INTO loans (book_id, member, days_out, borrowed_at) VALUES (${r.book_id}, '${r.member}', ${r.days_out}, '${r.borrowed_at}')`
  )
}
const { Pool } = db.adapters.createPg()
export const pool = new Pool()
